#include <map>
using namespace std;

class MyCalendarTwo {
    map<int, int> events;

public:
    MyCalendarTwo() {}

    bool book(int start, int end) {
        events[start]++;
        events[end]--;

        int active = 0;
        for (auto& event : events) {
            active += event.second;
            if (active > 2) {
                events[start]--;
                events[end]++;
                return false;
            }
        }
        return true;
    }
};
